 "isMyKind: other ^<Boolean> = (\n			^other isKindOfJSAlienView\n		)",
 "jsAlien ^<Alien> = (\n			^subject model reflectee\n		)",
 "properties ^<List[Fragment]> = (\n			| result <List[Fragment]> = List new. |\n			propertyNames with: propertyValues\n				do: [:pn <String> :pv <Alien> |\n					result add: (row: {(pv isKindOfJSAlien and: [ pv isUndefined ]) ifFalse: [\n									link: pn\n										action: [\n											enterSubject: (ObjectSubject onModel: (ObjectMirror reflecting: pv))\n										]\n								]\n								ifTrue: [ label: 'undefined' ]. mediumBlank. label: ([ pv printString ] on: Error\n									do: [:e | e printString ]). })\n				].\n			^result\n		)",
 "propertyNames ^<List[String]> = (\n			| ownProperties <Alien[Array[String]]> = JSObject getOwnPropertyNames: jsAlien. result <List[String]> = List new. |\n			1 to: (ownProperties at: #length)\n				do: [:i <Integer> | result add: (ownProperties at: i) ].\n			^result\n		)",
 "propertyValues ^<List[Alien | String]> = (\n			^propertyNames collect: [:p <String> |\n					[ jsAlien at: p ] on: Error do: [:e | e messageText ]\n				]\n		)",
