 "class LazySlotEvaluatorPresenter onSubject: s = EvaluatorPresenter onSubject: s (\n	)",
 "onSubject: s",
 "onSubject: s",
 "acceptResponse ^<[:CodeMirrorFragment :Event | Object]> = (\n			^[:ed <CodeMirrorFragment> :event <Event> |\n				| b <MixinBuilder> = subject method definingMixin asBuilder. canonical |\n				updateGUI: [\n						[\n							canonical:: ide prettyPrintLazySlotOr: ed textBeingAccepted.\n							b lazySlots addFromSource: canonical.\n							ide installFromBuilders: {b declaration. }.\n							ed text: canonical.\n							ide colorizer colorizeLazySlot: (crToLf: canonical)\n								fromClass: subject method definingMixin declaration\n								via: (colorizingBlockFor: ed).\n							ed leaveEditState\n						] on: Error do: [:ex <Exception> | ed showMessage: ex printString ]\n					].\n				ed editor focus\n			]\n		)",
 "cancelResponse ^<[:CodeMirrorFragment | Object]> = (\n			^[:ed <CodeMirrorFragment> |\n				ed text: subject method source.\n				ide colorizer colorizeLazySlot: (crToLf: subject method source)\n					fromClass: subject method definingMixin declaration\n					via: (colorizingBlockFor: ed).\n				ed leaveEditState\n			]\n		)",
 "deadChangeResponse ^<[:CodeMirrorFragment :Event | Object]> = (\n			^[:ed <CodeMirrorFragment> |\n				ide colorizer colorizeLazySlot: (crToLf: ed textBeingAccepted)\n					fromClass: subject method definingMixin declaration\n					via: (colorizingBlockFor: ed).\n				ed updateEditState.\n				ed editor focus\n			]\n		)",
 "editorDefinition ^<CodeMirrorFragment> = (\n			| initialSource |\n			initialSource:: subject initialSource.\n			cm:: (codeMirror: initialSource) acceptResponse: acceptResponse;\n				changeResponse: changeResponse;\n				cancelResponse: cancelResponse;\n				evaluateResponse: evaluateResponse;\n				useEditControls: true.\n			ide colorizer colorizeMethod: initialSource\n				fromClass: subject method definingMixin declaration\n				via: (colorizingBlockFor: cm).\n			^cm\n		)",
 "public isKindOfLazySlotEvaluatorPresenter ^<Boolean> = (\n			^true\n		)",
 "isMyKind: other ^<Boolean> = (\n			^other isKindOfLazySlotEvaluatorPresenter\n		)",
 "liveChangeResponse = (\n			^[:ed <CodeMirrorFragment> |\n				| src <String> = ed textBeingAccepted. |\n				updateGUI: [\n						subject evaluateLive: src withoutNbsp.\n						ide colorizer colorizeLazySlot: (crToLf: ed textBeingAccepted)\n							fromClass: subject method definingMixin declaration\n							via: (colorizingBlockFor: ed).\n						ed updateEditState\n					].\n				ed editor focus\n			]\n		)",
