 "commonSend: offset = (\n			0 = offset ifTrue: [ ^ordinarySend: #+ numArgs: 1 ].\n			1 = offset ifTrue: [ ^ordinarySend: #- numArgs: 1 ].\n			2 = offset ifTrue: [ ^ordinarySend: #* numArgs: 1 ].\n			3 = offset ifTrue: [ ^ordinarySend: #// numArgs: 1 ].\n			4 = offset ifTrue: [ ^ordinarySend: #\\\\ numArgs: 1 ].\n			5 = offset ifTrue: [ ^ordinarySend: #<< numArgs: 1 ].\n			6 = offset ifTrue: [ ^ordinarySend: #>> numArgs: 1 ].\n			7 = offset ifTrue: [ ^ordinarySend: #& numArgs: 1 ].\n			8 = offset ifTrue: [ ^ordinarySend: #| numArgs: 1 ].\n			9 = offset ifTrue: [ ^ordinarySend: #< numArgs: 1 ].\n			10 = offset ifTrue: [ ^ordinarySend: #> numArgs: 1 ].\n			11 = offset ifTrue: [ ^ordinarySend: #<= numArgs: 1 ].\n			12 = offset ifTrue: [ ^ordinarySend: #>= numArgs: 1 ].\n			13 = offset ifTrue: [ ^ordinarySend: #= numArgs: 1 ].\n			14 = offset ifTrue: [ ^ordinarySend: #new numArgs: 0 ].\n			15 = offset ifTrue: [ ^ordinarySend: #new: numArgs: 1 ].\n			16 = offset ifTrue: [ ^ordinarySend: #at: numArgs: 1 ].\n			17 = offset ifTrue: [ ^ordinarySend: #at:put: numArgs: 2 ].\n			18 = offset ifTrue: [ ^ordinarySend: #size numArgs: 0 ].\n			19 = offset ifTrue: [ ^ordinarySend: #value numArgs: 0 ].\n			20 = offset ifTrue: [ ^ordinarySend: #value: numArgs: 1 ].\n			21 = offset ifTrue: [ ^ordinarySend: #value:value: numArgs: 2 ].\n			22 = offset ifTrue: [ ^ordinarySend: #name numArgs: 0 ].\n			23 = offset ifTrue: [ ^ordinarySend: #name: numArgs: 1 ].\n			24 = offset ifTrue: [ ^ordinarySend: #add: numArgs: 1 ].\n			25 = offset ifTrue: [ ^ordinarySend: #hash numArgs: 0 ].\n			26 = offset ifTrue: [ ^ordinarySend: #yourself numArgs: 0 ].\n			27 = offset ifTrue: [ ^ordinarySend: #, numArgs: 1 ].\n			28 = offset ifTrue: [ ^ordinarySend: #and: numArgs: 1 ].\n			29 = offset ifTrue: [ ^ordinarySend: #or: numArgs: 1 ].\n			30 = offset ifTrue: [ ^ordinarySend: #not numArgs: 0 ].\n			31 = offset ifTrue: [ ^ordinarySend: #basicNew numArgs: 0 ].\n			^unusedBytecode\n		)",
 "interpretNext1Byte: byte = (\n			byte <= 15 ifTrue: [ ^jump: 0 - byte ].\n			byte <= 31 ifTrue: [ ^jump: byte & 15 ].\n			byte <= 47 ifTrue: [ ^popJumpTrue: byte & 15 ].\n			\n			(* Upstream decoded this range as popJumpTrue:; see the class comment of the module. *)\n			byte <= 63 ifTrue: [ ^popJumpFalse: byte & 15 ].\n			byte <= 79 ifTrue: [\n					^ordinarySend: (literalAt: byte & 7) numArgs: byte >> 3 & 1\n				].\n			byte <= 95 ifTrue: [ ^selfSend: (literalAt: byte & 7) numArgs: byte >> 3 & 1 ].\n			byte <= 111 ifTrue: [\n					^implicitReceiverSend: (literalAt: byte & 7) numArgs: byte >> 3 & 1\n				].\n			byte <= 119 ifTrue: [ ^pushParameter: byte & 7 ].\n			byte <= 127 ifTrue: [ ^pushLocal: byte & 7 ].\n			byte <= 135 ifTrue: [ ^popIntoLocal: byte & 7 ].\n			byte <= 143 ifTrue: [ ^storeIntoLocal: byte & 7 ].\n			byte <= 151 ifTrue: [ ^push: (literalAt: byte & 7) ].\n			byte = 152 ifTrue: [ ^push: nil ].\n			byte = 153 ifTrue: [ ^push: false ].\n			byte = 154 ifTrue: [ ^push: true ].\n			byte = 155 ifTrue: [ ^pushReceiver ].\n			byte = 156 ifTrue: [ ^pushMixin ].\n			byte = 158 ifTrue: [ ^pop ].\n			byte = 159 ifTrue: [ ^dup ].\n			byte = 160 ifTrue: [ ^push: -1 ].\n			byte = 161 ifTrue: [ ^push: 0 ].\n			byte = 162 ifTrue: [ ^push: 1 ].\n			byte = 163 ifTrue: [ ^push: 2 ].\n			byte = 166 ifTrue: [ ^returnLocal: nil ].\n			byte = 167 ifTrue: [ ^returnLocal: false ].\n			byte = 168 ifTrue: [ ^returnLocal: true ].\n			byte = 169 ifTrue: [ ^returnLocalReceiver ].\n			byte = 170 ifTrue: [ ^returnLocalTop ].\n			byte = 171 ifTrue: [ ^returnNonLocal: nil ].\n			byte = 172 ifTrue: [ ^returnNonLocal: false ].\n			byte = 173 ifTrue: [ ^returnNonLocal: true ].\n			byte = 174 ifTrue: [ ^returnNonLocalReceiver ].\n			byte = 175 ifTrue: [ ^returnNonLocalTop ].\n			byte <= 207 ifTrue: [ ^commonSend: byte - 176 ].\n			^unusedBytecode\n		)",
