 "public describe ^<String> = (\n			^'in ' , (nil = method ifTrue: [ '<root>' ] ifFalse: [ method selector ]) , ' at bci ' , bci printString , ' (frame ' , frame size printString , ', sp ' , stackPointer printString , ')'\n		)",
 "public outerContext ^<SimulatedActivation | nil> = (\n			(* The lexically enclosing activation, for block frames; nil for method frames. Part of the DebugMapper context protocol (NewspeakBytecodeCompilation DebugInfo). *)\n			\n			nil = closure ifTrue: [ ^nil ].\n			^closure definingActivation\n		)",
 "public pop = (\n			| value |\n			stackPointer < 1 ifTrue: [\n					Error signal: 'Simulated operand stack underflow ' , describe\n				].\n			value:: frame at: stackPointer.\n			frame at: stackPointer put: nil.\n			stackPointer:: stackPointer - 1.\n			^value\n		)",
 "public push: value = (\n			stackPointer:: stackPointer + 1.\n			stackPointer > frame size ifTrue: [ frame add: value ]\n				ifFalse: [ frame at: stackPointer put: value ]\n		)",
 "public resetForRestart = (\n			(* Reset this frame to its initial state, psoup Thread restart:withMethod: semantics: arguments (and, for closures, re-pushed copied values) survive; locals are cleared; the operand stack is emptied. *)\n			\n			| numArgs |\n			nil = closure ifTrue: [\n					numArgs:: method numArgs.\n					bci:: 1.\n					numArgs + 1 to: frame size do: [:i | frame at: i put: nil ].\n					stackPointer:: method numTemps\n				]\n				ifFalse: [\n					bci:: closure initialBCI.\n					closure numArgs + 1 to: frame size do: [:i | frame at: i put: nil ].\n					stackPointer:: closure numArgs.\n					1 to: closure copied size do: [:i | push: (closure copied at: i) ]\n				]\n		)",
 "public resetForStatementRestart = (\n			(* Re-enter at the failing statement's start with the locals AS CAPTURED (restored at transplant) and an empty operand stack - top-level statement boundaries hold no operands and no live control-flow context, so entry there is sound. Without a resolved statement (restartBci 1), or for a closure frame, degrade to the full restart (locals cleared): re-running from the method start must see nil locals, and the initializer statements will re-run. *)\n			\n			(1 = restartBci or: [ (nil = closure) not ]) ifTrue: [ ^resetForRestart ].\n			bci:: restartBci.\n			stackPointer:: method numTemps\n		)",
 "public size ^<Integer> = (\n			(* Current extent of the temp/operand area; DebugMapper context protocol. *)\n			\n			^stackPointer\n		)",
 "public size: numTemps <Integer> = (\n			(* Pre-establish the temp area, nil-filled, upstream Activation size: semantics. *)\n			\n			[ frame size < numTemps ] whileTrue: [ frame add: nil ].\n			stackPointer:: numTemps\n		)",
 "public tempAt: index <Integer> ^<Object> = (\n			(index between: 1 and: frame size) ifFalse: [\n					Error signal: 'Simulated temp index ' , index printString , ' out of range ' , describe\n				].\n			^frame at: index\n		)",
 "public tempAt: index <Integer> put: value <Object> = (\n			(index between: 1 and: frame size) ifFalse: [\n					Error signal: 'Simulated temp index ' , index printString , ' out of range ' , describe\n				].\n			frame at: index put: value\n		)",
