 "public class ExceptionTests new = TestContext new (\n	)",
 "new",
 "new",
 "nonLocalReturnCrossingExceptionHandler = (\n			[ ^'correct' ] on: Error do: [:ex | ^'wrong1' ].\n			^'wrong2'\n		)",
 "public testExceptionHandled = (\n			| beforeSignal ::= false. afterSignal ::= false. handler ::= false. exceptionSignaled exceptionHandled result |\n			result:: [\n				beforeSignal:: true.\n				exceptionSignaled:: Exception new.\n				exceptionSignaled signal.\n				afterSignal:: true.\n				42\n			] on: Exception\n				do: [:ex |\n					handler:: true.\n					exceptionHandled:: ex.\n					84\n				].\n			assert: beforeSignal.\n			deny: afterSignal.\n			assert: handler.\n			assert: exceptionSignaled equals: exceptionHandled.\n			assert: result equals: 84\n		)",
 "public testExceptionInvalidPass = (\n			| ex |\n			\n			(* Already handled. *)\n			ex:: Exception new.\n			[ ex signal ] on: Exception do: [:e |].\n			should: [ ex pass ] signal: Error.\n			\n			(* Already resumed. *)\n			ex:: Exception new.\n			[ ex signal ] on: Exception do: [:e | e resume: 42 ].\n			should: [ ex pass ] signal: Error.\n			\n			(* Already returned. *)\n			ex:: Exception new.\n			[ ex signal ] on: Exception do: [:e | e return: 42 ].\n			should: [ ex pass ] signal: Error.\n			\n			(* Never signaled. *)\n			ex:: Exception new.\n			should: [ ex pass ] signal: Error\n		)",
 "public testExceptionInvalidResume = (\n			| ex |\n			\n			(* Already handled. *)\n			ex:: Exception new.\n			[ ex signal ] on: Exception do: [:e |].\n			should: [ ex resume: 84 ] signal: Error.\n			\n			(* Already resumed. *)\n			ex:: Exception new.\n			[ ex signal ] on: Exception do: [:e | e resume: 42 ].\n			should: [ ex resume: 84 ] signal: Error.\n			\n			(* Already returned. *)\n			ex:: Exception new.\n			[ ex signal ] on: Exception do: [:e | e return: 42 ].\n			should: [ ex resume: 84 ] signal: Error.\n			\n			(* Never signaled. *)\n			ex:: Exception new.\n			should: [ ex resume: 84 ] signal: Error\n		)",
 "public testExceptionInvalidReturn = (\n			| ex |\n			\n			(* Already handled. *)\n			ex:: Exception new.\n			[ ex signal ] on: Exception do: [:e |].\n			should: [ ex return: 84 ] signal: Error.\n			\n			(* Already resumed. *)\n			ex:: Exception new.\n			[ ex signal ] on: Exception do: [:e | e resume: 42 ].\n			should: [ ex return: 84 ] signal: Error.\n			\n			(* Already returned. *)\n			ex:: Exception new.\n			[ ex signal ] on: Exception do: [:e | e return: 42 ].\n			should: [ ex return: 84 ] signal: Error.\n			\n			(* Never signaled. *)\n			ex:: Exception new.\n			should: [ ex return: 84 ] signal: Error\n		)",
 "public testExceptionPass = (\n			| beforeSignal ::= false. afterSignal ::= false. afterInnerTry ::= false. outerHandler ::= false. innerHandler ::= false. afterPass ::= false. |\n			[\n				[\n					beforeSignal:: true.\n					Exception new signal.\n					afterSignal:: true\n				] on: Exception\n					do: [:ex |\n						innerHandler:: true.\n						ex pass.\n						afterPass:: true\n					].\n				afterInnerTry:: true\n			] on: Exception do: [:ex | outerHandler:: true ].\n			assert: beforeSignal.\n			deny: afterSignal.\n			assert: innerHandler.\n			deny: afterPass.\n			deny: afterInnerTry.\n			assert: outerHandler\n		)",
 "public testExceptionResume = (\n			| beforeSignal ::= false. afterSignal ::= false. handler ::= false. afterResume ::= false. exceptionSignaled exceptionHandled signalResult result |\n			result:: [\n				beforeSignal:: true.\n				exceptionSignaled:: Exception new.\n				signalResult:: exceptionSignaled signal.\n				afterSignal:: true.\n				42\n			] on: Exception\n				do: [:ex |\n					handler:: true.\n					exceptionHandled:: ex.\n					ex resume: 63.\n					afterResume:: true.\n					84\n				].\n			assert: beforeSignal.\n			assert: afterSignal.\n			assert: handler.\n			deny: afterResume.\n			assert: exceptionSignaled equals: exceptionHandled.\n			assert: signalResult equals: 63.\n			assert: result equals: 42\n		)",
 "public testExceptionReturn = (\n			| beforeSignal ::= false. afterSignal ::= false. handler ::= false. afterReturn ::= false. exceptionSignaled exceptionHandled signalResult result |\n			result:: [\n				beforeSignal:: true.\n				exceptionSignaled:: Exception new.\n				signalResult:: exceptionSignaled signal.\n				afterSignal:: true.\n				42\n			] on: Exception\n				do: [:ex |\n					handler:: true.\n					exceptionHandled:: ex.\n					ex return: 63.\n					afterReturn:: true.\n					84\n				].\n			assert: beforeSignal.\n			deny: afterSignal.\n			assert: handler.\n			deny: afterReturn.\n			assert: exceptionSignaled equals: exceptionHandled.\n			assert: signalResult equals: nil.\n			assert: result equals: 63\n		)",
 "public testExceptionSignalInHandler = (\n			| outerBefore ::= false. outerAfter ::= false. innerBefore ::= false. innerAfter ::= false. innerExceptionSignaled innerExceptionCaught handlerExceptionSignaled outerExceptionCaught |\n			[\n				outerBefore:: true.\n				[\n					innerBefore:: true.\n					innerExceptionSignaled:: Exception new.\n					innerExceptionSignaled signal.\n					innerAfter:: true\n				] on: Exception\n					do: [:ex |\n						handlerExceptionSignaled:: Exception new.\n						handlerExceptionSignaled signal\n					].\n				outerAfter:: true\n			] on: Exception do: [:ex | outerExceptionCaught:: ex ].\n			assert: outerBefore.\n			assert: innerBefore.\n			deny: innerAfter.\n			deny: outerAfter.\n			assert: outerExceptionCaught equals: handlerExceptionSignaled\n		)",
 "public testExceptionTypeMatch1 = (\n			| beforeSignal ::= false. afterSignal ::= false. afterInnerTry ::= false. outerHandler ::= false. innerHandler ::= false. |\n			[\n				[\n					beforeSignal:: true.\n					Exception new signal.\n					afterSignal:: true\n				] on: TestException do: [:ex | innerHandler:: true ].\n				afterInnerTry:: true\n			] on: Exception do: [:ex | outerHandler:: true ].\n			assert: beforeSignal.\n			deny: afterSignal.\n			deny: innerHandler.\n			deny: afterInnerTry.\n			assert: outerHandler\n		)",
 "public testExceptionTypeMatch2 = (\n			| beforeSignal ::= false. afterSignal ::= false. afterInnerTry ::= false. outerHandler ::= false. innerHandler ::= false. |\n			[\n				[\n					beforeSignal:: true.\n					TestException new signal.\n					afterSignal:: true\n				] on: TestException do: [:ex | innerHandler:: true ].\n				afterInnerTry:: true\n			] on: Exception do: [:ex | outerHandler:: true ].\n			assert: beforeSignal.\n			deny: afterSignal.\n			assert: innerHandler.\n			assert: afterInnerTry.\n			deny: outerHandler\n		)",
 "public testExceptionTypeMatch3 = (\n			| beforeSignal ::= false. afterSignal ::= false. afterInnerTry ::= false. outerHandler ::= false. innerHandler ::= false. |\n			[\n				[\n					beforeSignal:: true.\n					TestException new signal.\n					afterSignal:: true\n				] on: Exception do: [:ex | innerHandler:: true ].\n				afterInnerTry:: true\n			] on: TestException do: [:ex | outerHandler:: true ].\n			assert: beforeSignal.\n			deny: afterSignal.\n			assert: innerHandler.\n			assert: afterInnerTry.\n			deny: outerHandler\n		)",
 "public testNonLocalReturnCrossingExceptionHandler = (\n			assert: nonLocalReturnCrossingExceptionHandler equals: 'correct'\n		)",
