 "public testRegularSlotImmutable = (\n			| out |\n			out:: printSlotOf: 'private foo = 42.'.\n			assert: (out indexOf: 'private') > 0.\n			assert: (out indexOf: 'foo') > 0.\n			assert: (out indexOf: '=') > 0.\n			assert: (out indexOf: '42') > 0\n		)",
 "public testRegularSlotMutable = (\n			| out |\n			out:: printSlotOf: 'public bar ::= 99.'.\n			assert: (out indexOf: 'public') > 0.\n			assert: (out indexOf: 'bar') > 0.\n			assert: (out indexOf: '::=') > 0.\n			assert: (out indexOf: '99') > 0\n		)",
 "public testRelaxedMemberOrderMethodBeforeLazyBeforeClass = (\n			(* Members may be written in any order; the AST still bins them\n	   by category and the printer canonicalises on output. *)\n			\n			| src ast |\n			src:: 'class Foo = () (\n		first = (^1)\n		lazy public l = 7.\n		class Inner = () () : ()\n		second = (^2)\n	) : ()'.\n			ast:: [ commonParser parseClassDeclaration: src ] on: Exception\n				do: [:e |\n					assert: false description: 'parse failed: ' , e messageText.\n					^self\n				].\n			assert: ast instanceSide methods size = 2\n				description: 'expected 2 methods, got ' , ast instanceSide methods size printString.\n			assert: ast instanceSide lazySlots size = 1\n				description: 'expected 1 lazy slot'.\n			assert: ast instanceSide nestedClasses size = 1\n				description: 'expected 1 nested class'\n		)",
 "public testRoundtripClass = (\n			| src out reparseOk |\n			src:: 'class Foo = (| x = 1. |)(public m = (^x)) : (public new = (^Foo))'.\n			out:: printClassOf: src.\n			reparseOk:: [\n				commonParser parseClassDeclaration: out.\n				true\n			] on: Exception do: [:e | false ].\n			assert: reparseOk\n		)",
 "public testRoundtripExpression = (\n			| src out reparseOk |\n			src:: 'a at: 1 + 2 put: foo bar baz'.\n			out:: printExpr: src.\n			reparseOk:: [\n				commonParser parseExpression: out.\n				true\n			] on: Exception do: [:e | false ].\n			assert: reparseOk\n		)",
 "public testRoundtripMethod = (\n			| src out reparseOk |\n			src:: 'public foo: x bar: y = (| t | t:: x + y. ^t)'.\n			out:: printMethodOf: src.\n			reparseOk:: [\n				commonParser parseMethodDeclaration: out.\n				true\n			] on: Exception do: [:e | false ].\n			assert: reparseOk\n		)",
 "public testScientificNotation = (\n			| out |\n			out:: prettyPrinting prettyPrintExpression: '1.5e3'.\n			assert: (out indexOf: '1.5e3') > 0\n		)",
