 "public testSetterValueAcceptsKeywordSendWithoutParens = (\n			(* Setter syntax accepts a full statement-level expression on the\n	   right; 'x:: m at: 1' should NOT print as 'x:: (m at: 1)'. *)\n			\n			| out |\n			out:: prettyPrinting prettyPrintExpression: 'x:: m at: 1'.\n			deny: (out indexOf: '(m at:') > 0.\n			assert: (out indexOf: '::') > 0.\n			assert: (out indexOf: 'at:') > 0\n		)",
 "public testSingleStatementBlock = (\n			| out |\n			out:: printExpr: '[42]'.\n			assert: (out indexOf: '[') > 0.\n			assert: (out indexOf: '42') > 0.\n			assert: (out indexOf: ']') > 0\n		)",
 "public testSlotWithType = (\n			| out |\n			out:: printSlotOf: 'public count <Integer> ::= 0.'.\n			assert: (out indexOf: 'Integer') > 0.\n			assert: (out indexOf: 'count') > 0\n		)",
 "public testSlotWithUnionType = (\n			| out |\n			out:: printSlotOf: 'private value <String | Nil> = nil.'.\n			assert: (out indexOf: 'String') > 0.\n			assert: (out indexOf: 'Nil') > 0.\n			assert: (out indexOf: '|') > 0\n		)",
 "public testSourceApiClass = (\n			| out |\n			out:: prettyPrinting prettyPrintClass: 'class Foo = (| x = 1. |)(public m = (^x)) : (public new = (^Foo))'.\n			assert: (out indexOf: 'Foo') > 0.\n			assert: (out indexOf: 'm') > 0.\n			assert: (out indexOf: 'new') > 0\n		)",
 "public testSourceApiClassHeader = (\n			(* A class header with slot bar but no body. The source-based\n	   prettyPrintClassHeader: should emit a recognisable header. *)\n			\n			| out |\n			out:: prettyPrinting prettyPrintClassHeader: 'class Foo = Bar (| public x = 1. |)'.\n			assert: (out indexOf: 'class') > 0.\n			assert: (out indexOf: 'Foo') > 0.\n			assert: (out indexOf: 'Bar') > 0.\n			assert: (out indexOf: 'x') > 0\n		)",
 "public testSourceApiCompilationUnit = (\n			(* prettyPrintCompilationUnit: parses a complete .ns file (language\n	   ID line + category string + class declaration) and emits all\n	   three. Round-trip via parseCompilationUnit:. *)\n			\n			| src out reparseOk lf |\n			lf:: String lf.\n			src:: 'Newspeak3' , lf , '''Root''' , lf , 'class Foo = (| x = 1. |)(public m = (^x)) : (public new = (^Foo))'.\n			out:: prettyPrinting prettyPrintCompilationUnit: src.\n			assert: (out indexOf: 'Newspeak3') > 0.\n			assert: (out indexOf: 'Root') > 0.\n			assert: (out indexOf: 'class Foo') > 0.\n			reparseOk:: [\n				commonParser parseCompilationUnit: out.\n				true\n			] on: Exception do: [:e | false ].\n			assert: reparseOk\n		)",
