 "public testSourceApiMethod = (\n			| out |\n			out:: prettyPrinting prettyPrintMethod: 'public foo = (^42)'.\n			assert: (out indexOf: 'public') > 0.\n			assert: (out indexOf: 'foo') > 0.\n			assert: (out indexOf: '42') > 0\n		)",
 "public testSourceApiStatement = (\n			| out |\n			out:: prettyPrinting prettyPrintStatement: '^foo + bar'.\n			assert: (out indexOf: '^') > 0.\n			assert: (out indexOf: 'foo') > 0.\n			assert: (out indexOf: 'bar') > 0\n		)",
 "public testString = (\n			assert: (printExpr: '''hello''') equals: '''hello'''\n		)",
 "public testStringContainingOpenCommentMarkerDoesNotCrash = (\n			(* Bug repro: when a chunk fed to MetadataParser contains an\n	   open-comment marker inside a quoted string, the scanner\n	   thinks a comment opened, walks off the end, and DNUs on its\n	   own missing scanError:. The printer must now tolerate the\n	   failure via on:Error do:.\n\n	   Construct the test source at runtime via concatenation so\n	   this test file's own source does NOT literally contain the\n	   problematic '(' + '*' sequence in a string — that would\n	   confuse the .ns scanner, which doesn't know whether it's\n	   looking at code or a comment until it sees the opener. *)\n			\n			| openMarker src out reparseOk |\n			openMarker:: '(' , '*'.\n			src:: 'foo = (^''has ' , openMarker , ' in it'')'.\n			out:: [ prettyPrinting prettyPrintMethod: src ] on: Error\n				do: [:e |\n					assert: false\n						description: 'string with open-comment marker crashed: ' , e printString.\n					^self\n				].\n			reparseOk:: [\n				commonParser parseMethodDeclaration: out.\n				true\n			] on: Error do: [:e | false ].\n			assert: reparseOk\n		)",
 "public testStringWithEmbeddedQuote = (\n			assert: (printExpr: '''don''''t''') equals: '''don''''t'''\n		)",
 "public testSymbol = (\n			assert: (printExpr: '#foo') equals: '#foo'\n		)",
 "public testSymbolWithAtIsQuoted = (\n			(* Bug repro: '#''@here''' has identifier-start preceded by '@'\n	   (a binary char) — neither pure-identifier nor pure-binary, so\n	   must be quoted. *)\n			\n			| out reparseOk |\n			out:: prettyPrinting prettyPrintExpression: '#''@here'''.\n			deny: (out indexOf: '#@') > 0.\n			reparseOk:: [\n				commonParser parseExpression: out.\n				true\n			] on: Error do: [:e | false ].\n			assert: reparseOk\n		)",
 "public testSymbolWithBackticksIsQuoted = (\n			(* Bug repro: symbols like '#''bottom`''' (with backticks) were\n	   emitted bare; the scanner raised 'Unknown token' on '`'. *)\n			\n			| out reparseOk |\n			out:: prettyPrinting prettyPrintExpression: '#''bottom``'''.\n			assert: (out indexOf: '''') > 0.\n			reparseOk:: [\n				commonParser parseExpression: out.\n				true\n			] on: Error do: [:e | false ].\n			assert: reparseOk\n		)",
 "public testSymbolWithSemicolonIsQuoted = (\n			(* Bug repro: ';' was wrongly included in the binary-char set,\n	   so '#'';''' was emitted bare as '#;', which 'scanSymbol'\n	   rejects (semicolon isn't in isSpecialCharacter). *)\n			\n			| out reparseOk |\n			out:: prettyPrinting prettyPrintExpression: '#'';'''.\n			deny: (out indexOf: '#;') > 0.\n			reparseOk:: [\n				commonParser parseExpression: out.\n				true\n			] on: Error do: [:e | false ].\n			assert: reparseOk\n		)",
 "public testSymbolWithSetterMarkerIsQuoted = (\n			(* Bug repro: '#''::=''' is the setter-operator selector. Bare\n	   '#::=' raises 'Invalid symbol literal' because ':' isn't a\n	   special character for scanSymbol. *)\n			\n			| out reparseOk |\n			out:: prettyPrinting prettyPrintExpression: '#''::='''.\n			deny: (out indexOf: '#::=') > 0.\n			reparseOk:: [\n				commonParser parseExpression: out.\n				true\n			] on: Error do: [:e | false ].\n			assert: reparseOk\n		)",
 "public testTrailingSlotCommentStaysOnItsSlot = (\n			(* A comment at the end of a slot's line documents THAT slot, not\n	   the next one. Printing it as the next slot's leading comment\n	   shifts a whole slot bar's documentation down by one -- which is\n	   how 'Must be slot 1' came to label slot 2 in KernelForSqueak. *)\n			\n			| out |\n			out:: printClassOf: 'class Host = Object new (\n	| a <Integer> (* ABOUT A *) b <Integer> (* ABOUT B *) |\n) () : ()'.\n			assert: (out indexOf: 'a <Integer> (* ABOUT A *)') > 0\n				description: 'expected the comment to stay on a''s line: ' , out.\n			assert: (out indexOf: 'b <Integer> (* ABOUT B *)') > 0\n				description: 'expected the comment to stay on b''s line: ' , out\n		)",
 "public testTrueLiteral = (\n			assert: (printExpr: 'true') equals: 'true'\n		)",
